import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

// Storage examples: pt_user {name:'Asha',email:'asha@example.test',avgCycle:28,periodLength:5,focusAreas:[]}; pt_cycles [{id,startDate,endDate,notes,intensity}]; pt_diet/pt_exercise [{id,text,date}]; pt_symptoms [{id,symptom,severity,date}]; pt_medication [{id,name,dose,time,log:[]}]; pt_settings {darkMode:false,discreet:false,theme:'flower',medicationReminders:false}; pt_trash [{id,type,item,deletedAt}]; pt_shares {id:{snapshot,expiresAt}}; pt_analytics_cache {simulatedAt,days:[]}.
const KEYS = ['pt_user','pt_cycles','pt_diet','pt_exercise','pt_symptoms','pt_medication','pt_settings','pt_trash','pt_shares','pt_analytics_cache'];
const defaults = { pt_user:null, pt_cycles:[], pt_diet:[], pt_exercise:[], pt_symptoms:[], pt_medication:[], pt_settings:{}, pt_trash:[], pt_shares:{}, pt_analytics_cache:null };
const CLOUD_MODE = import.meta.env.VITE_CLOUD_MODE === 'true';
